foreach (['admin-page-row__heading','admin-page-row__layout','forms-column__header','forms-column__content','forms-column__add','forms-builder__add','forms-field','data-forms-row-drag','data-forms-edit-field','data-forms-remove-field','data-forms-remove-row','data-forms-column-count'] as $token) $check(str_contains($view,$token),"Uses common Builder structure: $token");
foreach (['data-forms-row-up','data-forms-row-down',"admin_icon_action_button('arrow-up'","admin_icon_action_button('arrow-down'"] as $token) $check(!str_contains($view,$token),"Old row arrows removed: $token");
