$check(version_compare((string)(preg_match("/BOILERPLATE_VERSION', '([^']+)'/",(string)file_get_contents($root.'/public_html/incl/init.php'),$m)?$m[1]:''),'2.4.4.55','>='),'Version >= 2.4.4.55');
$check(!str_contains($view,'[data-forms-row-up]') && !str_contains($view,'[data-forms-row-down]'),'No JS queries old visible arrows');
